CREATE TABLE IF NOT EXISTS exercises (
  id INT AUTO_INCREMENT PRIMARY KEY,
  slug VARCHAR(100) NOT NULL UNIQUE,
  name_cs VARCHAR(255) NOT NULL,
  name_en VARCHAR(255) NULL,
  category VARCHAR(100) NOT NULL,
  calc_unit ENUM('duration','distance_km','reps') NOT NULL DEFAULT 'duration',
  met DECIMAL(5,2) NULL,
  kcal_per_rep DECIMAL(6,3) NULL,
  kcal_per_km_per_kg DECIMAL(6,3) NULL,
  default_amount DECIMAL(8,2) NULL,
  intensity VARCHAR(50) NULL,
  note TEXT NULL,
  source_url VARCHAR(500) NULL,
  active TINYINT(1) NOT NULL DEFAULT 1,
  created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Výpočet v aplikaci:
-- duration: kcal = met * user_weight_kg * (minutes / 60)
-- distance_km: kcal = kcal_per_km_per_kg * user_weight_kg * distance_km
-- reps: kcal = kcal_per_rep * reps
